import type { MoveRecord } from '@chess-open/core';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { Platform } from 'react-native';

import { useSettings, type SoundSet } from '@/store/settings';

/** Sound events (ТЗ §10 «Звук и вибро»). Files are generated by tools/sounds/generate.py. */
export type SoundName = 'move' | 'capture' | 'castle' | 'check' | 'correct' | 'wrong' | 'complete';

const SOURCES: Record<Exclude<SoundSet, 'off'>, Record<SoundName, number>> = {
  wood: {
    move: require('@/assets/sounds/wood/move.wav'),
    capture: require('@/assets/sounds/wood/capture.wav'),
    castle: require('@/assets/sounds/wood/castle.wav'),
    check: require('@/assets/sounds/wood/check.wav'),
    correct: require('@/assets/sounds/wood/correct.wav'),
    wrong: require('@/assets/sounds/wood/wrong.wav'),
    complete: require('@/assets/sounds/wood/complete.wav'),
  },
  soft: {
    move: require('@/assets/sounds/soft/move.wav'),
    capture: require('@/assets/sounds/soft/capture.wav'),
    castle: require('@/assets/sounds/soft/castle.wav'),
    check: require('@/assets/sounds/soft/check.wav'),
    correct: require('@/assets/sounds/soft/correct.wav'),
    wrong: require('@/assets/sounds/soft/wrong.wav'),
    complete: require('@/assets/sounds/soft/complete.wav'),
  },
};

const players = new Map<string, AudioPlayer>();
let audioModeSet = false;

function player(set: Exclude<SoundSet, 'off'>, name: SoundName): AudioPlayer {
  const key = `${set}/${name}`;
  let p = players.get(key);
  if (!p) {
    p = createAudioPlayer(SOURCES[set][name]);
    players.set(key, p);
  }
  return p;
}

/** Create the players of a set up front so the first sound has no delay. */
export function preloadSounds(set: SoundSet = useSettings.getState().soundSet): void {
  if (set === 'off') return;
  if (!audioModeSet) {
    audioModeSet = true;
    // Game sounds must not stop the user's music.
    void setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(
      () => undefined,
    );
  }
  for (const name of Object.keys(SOURCES[set]) as SoundName[]) player(set, name);
}

export function playSound(name: SoundName): void {
  const set = useSettings.getState().soundSet;
  if (set === 'off') return;
  try {
    const p = player(set, name);
    void p.seekTo(0);
    p.play();
  } catch {
    // Audio is best-effort; never break a move because of it.
  }
}

export type HapticKind = 'move' | 'capture' | 'error' | 'success';

/** Vibration — phones only; silently disabled on web (ТЗ module 7). */
export function haptic(kind: HapticKind): void {
  if (Platform.OS === 'web' || !useSettings.getState().haptics) return;
  const run = (): Promise<void> => {
    switch (kind) {
      case 'move':
        return Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      case 'capture':
        return Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      case 'error':
        return Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
      case 'success':
        return Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    }
  };
  void run().catch(() => undefined);
}

/** Sound + vibration for a played move. */
export function moveFeedback(move: MoveRecord): void {
  if (move.check) playSound('check');
  else if (move.castle) playSound('castle');
  else if (move.captured) playSound('capture');
  else playSound('move');
  haptic(move.captured ? 'capture' : 'move');
}

export function wrongFeedback(): void {
  playSound('wrong');
  haptic('error');
}

export function successFeedback(): void {
  playSound('complete');
  haptic('success');
}
